(function(g){'use strict';
// Authored against the implemented engines. Explanations do not change inference or evaluation.
const roles={
m1:['多特征加权kNN','颜色接近的颗粒仍可能有不同纹理和形状。把同一颗粒的特征按训练尺度比较，再由距离较近的参考颗粒加权投票。','选一个颗粒，对照近邻、颜色基线，以及整盘颗粒数和面积比例。'],
m2:['累计体积归位＋加权kNN','累计泵量把地面气峰连回较早的来源时段；组分与工况一起进入近邻距离，使相似气峰能够按不同作业背景比较。','保持同一气峰，切换工况，查看前三个近邻、支持度和候选解释怎样变化。'],
m3:['曝光校正＋像素逻辑回归','先校正曝光，再把同一像素的颜色和亮度特征乘以学得权重，得到显示得分；阈值将得分转成可计数的范围。','比较三种方法的掩膜、检出像素和同一分母下的面积比例。'],
m4:['工况回归＋k均值与连续分段','回归先估计钻压、转速等工况应产生的响应；校正后的相对变化再参与分组和连续分段，减少把操作变化看成地层界面的机会。','切换工况校正，对照共同深度轴上的残差、响应分组和候选界面。'],
m5:['字符朴素贝叶斯＋字段抽取','文本分类按学到的字符词项决定记录去向，字段规则保留数值、单位、否定和井段范围，再把这些资料组装成可回查的报告。','改变原文中的“未见／见”或数值，比较字段、分流和报告句子，并点击句子回查来源。'],
d1:['多项式岭回归＋约束网格搜索','回归用十项特征学习工况与钻速的关系，岭约束控制系数；搜索只在满足边界的候选里比较预测钻速。','同时读推荐点、约束余量和留出误差，检查高预测值是否仍满足工况限制。'],
g1:['多波段特征kNN','红光、近红外和短波红外记录不同响应，联合特征可区分在红光中相似的岩石、植被与阴影。近邻给出可回看的参考图幅。','对照只留红光与多特征分类，点同一像素查看近邻和误分位置。'],
g2:['背景协方差与马氏距离','背景组分常一起波动。联合距离按背景的伸展方向衡量偏离，区别共同背景变化与不寻常的组分组合。','在地图和交会图中选同一点，对照联合距离与单C1门槛的误报、召回。'],
g3:['图块模板距离＋图例字段抽取','将二值图块逐像素与模板比较，可保留符号形状信息；图例文字另行抽取字段，再用类别关联图块。','增加噪声，比较模板距离、图块类别和规则基线。'],
g4:['Hough直线投票','同一直线上的暗像素在参数空间投向相同位置，累积投票把分散的像素线索汇成候选裂缝。','改变票数门槛，检查检出线、漏掉的弱裂缝，以及条数和长度两种统计。'],
s1:['局部特征逻辑回归','错断会同时改变反射连续性和局部方向。分类器学习这些特征的权重，比只对一个不连续性属性设门槛多利用了结构信息。','选择同一位置，对照原剖面、候选得分、迹线和阈值基线。'],
s2:['反射小窗四维kNN','振幅相近的小窗可能有不同连续性与形态。把多种属性放在同一训练尺度上，用近邻比较整个反射样式。','改变近邻数或噪声，回看当前小窗的近邻类别、支持度和单属性基线。'],
s3:['波前特征逻辑回归','初至附近的能量和波形变化可组合成得分，既利用起跳强度，也利用前后变化，帮助区分弱到达与孤立尖峰。','在同一道上比较拾取点、幅度门槛、时间误差和未拾取数量。'],
s4:['多属性回归','井震标定让地震属性与井上孔隙度对应。第二属性可补充相同阻抗下的差异，回归系数将这些信息组合为预测。','在留出井共同深度轴上，对照多属性、单属性和井上参考曲线。'],
s5:['邻域回归去噪','相邻道的反射具有相关性。由邻域振幅学习目标响应，可以利用空间联系压低不一致的干扰。','同时查看处理后炮集与移除差值，再比较简单平滑和误差。'],
d2:['正常关系回归与残差告警','先学正常工况下响应应怎样变化，再观察实测偏离；持续残差把工况引起的正常波动与异常线索分开比较。','对照实测、正常预期、残差和报警时段，检查无可见先兆时的结果。'],
d3:['标定转向模型＋约束候选搜索','标定学习转向指令与轨迹变化的对应关系，搜索逐步比较可行指令对目标误差和动作幅度的影响。','比较目标、实际轨迹与固定指令基线，检查控制约束。'],
d4:['振动特征逻辑回归','工具状态会改变振动能量和频率结构。分类器组合多个振动特征，而不是把单次振幅升高直接当作状态改变。','选同一信号窗，连接波形、频谱、分类得分和留出评价。'],
d5:['流变响应面＋配方搜索','由试验批次学习配比与塑性黏度的关系，再枚举满足用量和代价边界的配方。响应面支持在多个输入之间比较。','比较推荐配方、当前响应和固定配方，检查可行域与误差。'],
w1:['两侧窗口分类＋边界合并','界面两侧的曲线水平和变化幅度往往不同。分类器比较两侧特征，邻近候选再合并为可逐一核查的界面。','改变阈值，对照原曲线、候选边界和一对一匹配结果。'],
w2:['标定回归','岩心孔隙度提供标定目标，回归从测井响应中学习映射；与固定公式比较，可看到标定对当前数据关系的作用。','点选留出记录，对照预测、公式和误差位置。'],
w3:['局部结构分类','裂缝在展开图上形成有方向的局部纹理。分类器组合邻域特征，区分结构线索和单个暗像素。','对照原展开图、候选叠加和单阈值基线，查看漏检与误检。'],
w4:['标准化多曲线kNN','不同测井通道补充不同地层响应。统一量纲后比较邻近记录，避免数值范围大的通道支配距离。','沿深度选择一点，对照近邻投票、GR规则与整井留出结果。'],
w5:['辅助曲线近邻回归','缺口处仍可见的辅助曲线用于寻找训练样本，由相似记录估计缺失密度响应。','调整可用通道，比较缺口预测、简单插值和封存参考曲线。'],
c1:['声波特征kNN','声波幅度、衰减等特征共同反映传播响应，近邻用多个线索比较相似胶结记录，并保留低支持度对象供回查。','选择同井窗口，对照波形、四维特征、近邻和单属性基线。'],
c2:['双输出回归代理＋约束搜索','试验记录让模型同时学习两类顶替响应，搜索在共同约束下比较方案，避免只优化其中一个指标。','比较推荐与固定方案的两个响应及可行性。'],
c3:['联合风险分类','多项井况一起影响漏失线索。模型学习联合关系，再按阈值形成复核名单。','调整门槛，同时查看候选名单、漏报和误报。'],
c4:['间隙回归代理','载荷与支撑布置共同改变窄侧间隙。代理由样本学习关系，再沿井段寻找最窄位置。','改变扶正布置，比较最小间隙、位置与简化估计。'],
co1:['历史近邻响应估计＋条件筛选','相似井况的历史结果提供候选方案响应；先排除不满足条件的方案，再按同一效用比较。','对照各方案近邻、筛除理由与固定方案。'],
co2:['层内动作枚举＋跨层约束推理','逐层可行并不保证组合可行。枚举动作后传播跨层限制，才能比较完整分层方案。','改变边界条件，查看被筛除的组合、原因和排序。'],
co3:['双分量应力回归','压力和温度边界对应不同应力分量，分别学习再合成，有助于沿井段定位响应集中的位置。','对照两个应力分量、合成响应与简化估算。'],
co4:['学习动作响应＋逐日约束搜索','模型从分段动作样本估计响应，每天在可行组合中选择，再推进状态，因此今天的动作会改变后续条件。','比较控制轨迹、当天动作、累计结果和固定策略。'],
p1:['射孔代理回归＋可行域搜索','试验学习几何参数与响应的关系，搜索同时检查代价和拥挤等限制，在可行集合内比较效果。','读推荐点、被排除方案与固定设计，检查约束和留出误差。'],
p2:['双目标回归代理','材料条件对孔道长度与入口尺寸的影响不同。模型学习两个输出，支持同一输入下的联合比较。','改变材料条件，比较两个输出与简单基线。'],
p3:['目录规则推理＋可行集合排序','通径、温度等硬条件逐项剔除不适用条目，再在可行集合中排序，使每次排除都有可回看的依据。','对照逐条条件、候选变化和只看单条件的结果。'],
p4:['工况回归校正','作业前后产量变化同时包含工况变化。回归先估计工况对应的响应，再把剩余变化单独呈现。','比较实际变化、工况预期和剩余响应，并回看原井记录。'],
pr1:['功图形状kNN','完整循环的形状特征保留载荷随位移的变化，近邻可以区分面积相近但形状不同的功图。','选同一循环，对照形状特征、近邻与面积基线。'],
pr2:['滞后特征回归与递归预测','近期产量与变化提供时间线索；模型由截止日前资料拟合，再把前一步预测送入下一天。','对照整段未来曲线、持续值基线和误差，观察逐步累积的偏差。'],
pr3:['分层响应回归＋守恒搜索','各层对注水量的响应不同。学习各层曲线后，在总量守恒和层内边界下比较配额。','比较推荐配额与均分方案，核对总量和各层响应。'],
pr4:['正常温度回归＋残差告警','负荷和电流会影响正常温度。先估计这部分变化，再对持续偏离告警，可与固定温度门槛作区分。','将温度、预期和残差放在同一时间轴，比较报警位置。'],
pr5:['多变量逻辑回归','温度、压差等条件共同形成风险线索，逻辑回归学习组合权重并输出得分，门槛决定复核范围。','比较联合输入与单变量的分数分布、误报和漏报。'],
wo1:['词项与数值联合相似度检索','井史文字和本次观测各自提供相似性线索，联合距离找历史记录，再用显式条件筛选可用候选。','查看候选来源、相似度分解、筛除理由和关键词基线。'],
wo2:['工具关系检索＋硬约束推理','先沿工具关系找到候选，再检查通径和拉力，避免只因尺寸匹配就选用不满足载荷条件的工具。','逐项改变条件，比较候选集合与单尺寸基线。'],
wo3:['偏心背景拟合＋残差分割','偏心会形成跨方位的共同变化。拟合背景后，正残差突出局部内半径异常，便于量测缺陷区域。','比较原始矩阵、拟合背景、残差掩膜与原始阈值。'],
wo4:['正常载荷回归＋连续残差检测','速度影响正常载荷。学习正常关系后对持续偏离合成事件，减少将普通操作变化直接作为异常。','对照载荷、速度、预期、残差和报警时刻。'],
wo5:['负荷特征回归','完整检修间隔与运行负荷提供样本对应，回归学习不同负荷下的间隔差异。','比较当前间隔估计、固定间隔和独立设备误差。'],
e1:['双响应代理＋受约束搜索','增油与压力响应由独立试验学习，候选搜索在成本和压力限制内比较两个目标。','查看推荐点、固定方案、Pareto候选与约束余量。'],
e2:['半长与半高回归','施工和地层条件影响两个几何尺度，分别回归后重建椭圆，使参数变化能对应到轮廓变化。','对照预测轮廓、参考轮廓与半长半高误差。'],
e3:['混合物响应代理＋单纯形搜索','混合比例总和固定，组分间还存在交互。回归学习响应后，只在比例与成本可行的组合中比较。','在配比图上比较可行性能、代价与固定配方。'],
e4:['周期产油回归＋约束搜索','注汽、焖井与生产时长共同影响周期产油。模型学习这些联系，再检查蒸汽用量边界并排序。','同时查看累计产油、用汽量和质量汽油比，比较固定周期。'],
e5:['标准化kNN回归','培养环境的多个条件一起决定样本相似性，用相似培养记录的活性估计当前响应。','改变条件或k，比较实际近邻、活性响应和留出误差。'],
t1:['正常流量回归＋事件检测','正常出口随入口和压力变化。回归估计正常响应，持续偏差再合成待核查时段。','对照入口出口、正常预期、残差和事件匹配。'],
t2:['坐标配准＋多属性缺陷匹配','先对齐两次检测坐标，再匹配同一位置的缺陷，避免把里程错位读成新的腐蚀或增长。','改变偏移与噪声，比较匹配、增长排序和未配准结果。'],
t3:['泵组候选枚举＋约束寻优','不同泵组组合承担同一输送任务的能耗与边界不同；逐项计算候选并筛选可行组合。','比较推荐、固定组合、能耗和输送任务余量。'],
t4:['比例与零点回归校准','多组参考计量读数用于同时拟合比例和零点，分别纠正随流量放大的偏差与固定偏移。','对照原始与校正流量、累计计量差和标定窗口。'],
t5:['图像液面提取＋多源交叉核查','图像边缘给出液面位置，标尺换算为高度，再与罐表和仪表读数比较，暴露不一致的来源。','调整图像条件，查看检测线、高度换算和多帧误差。'],
r1:['多输出代理＋约束搜索','温度等操作量同时影响多个响应。分别拟合代理，再联合检查产品与能耗条件，比较完整工况。','查看推荐点、可行域、固定方案和各代理误差。'],
r2:['产物回归＋组成约束','原料和操作共同影响各产物。模型学习多项产物响应，再施加总和约束，使组成可以一起比较。','改变输入，比较六项产物、总和与留出误差。'],
r3:['正常状态回归＋趋势提醒','设备负荷改变正常观测。先估计负荷对应的响应，再用独立验证设置残差门槛，观察持续偏离。','对照实测、预期、趋势、固定阈值和提醒时段。'],
r4:['字段规则＋正常指标关系回归','先把化验原文转换为带单位字段，再检查正常样品中指标的联合关系，区分格式问题与数值不一致。','修改原文，逐项查看抽取、量纲检查、关系残差和异常证据。'],
r5:['多变量质量软测量','过程变量与化验样品按采样时刻对齐后，回归学习过程量到质量的关系，在两次化验之间形成估计。','比较软测量、最新化验保持值和单变量估计，检查漂移与误差。'],
's17x-g3-closure-spill':['优先队列连通分析','从高点逐步提高允许深度，寻找第一次与开放边界连通的位置，整张网格的出口共同决定闭合。','改变侧向出口，对照平面范围、溢出点和只看一条剖面的结果。'],
's17x-c1-cement-woc-strength':['等效龄期＋单调强度拟合','温度历史先积分为等效龄期，再用独立批次拟合强度关系，使不同养护历史可在同一尺度比较。','改变温度历史与目标强度，对照达标时刻和忽略温度的龄期曲线。'],
's17x-co3-completion-seal-test':['温漂校准＋补偿后回归','独立无漏校准估计温度引起的压力变化；补偿后再拟合保压斜率，分开比较温漂和剩余压降。','在同一保压窗内比较原压、温度、补偿曲线和漏率区间。'],
's17x-p1-perforation-depth-correlation':['GR互相关＋CCL有序匹配','GR形状提供偏移候选，整组接箍顺序再核对；两类线索共同检查深度对准和重复匹配。','沿两把深度尺查看目标层落点、漏检和多个匹配候选。']
};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function mount(){
 const m=g.S17CompassPage?.model;if(!m)return;
 const spec=roles[m.current.id]||roles[m.scene.id],lab=document.getElementById('lab')||document.querySelector('[data-panel="demo"]');if(!spec||!lab||lab.querySelector('[data-method-role]'))return;
 if(lab.matches('[data-panel="demo"]')&&g.location.hash==='#lab')document.querySelector('button[data-tab="demo"]')?.click();
 const el=document.createElement('aside');el.className='method-role';el.dataset.methodRole=m.current.id;
 el.innerHTML='<div class="method-role-heading"><span>本次计算的方法</span><strong>'+esc(spec[0])+'</strong><a href="#method-current-result" data-method-result>对照当前结果 ↓</a></div><div class="method-role-copy"><p><b>为什么这样算</b>'+esc(spec[1])+'</p><p><b>从哪里看出作用</b>'+esc(spec[2])+'</p></div>';
 const actions=lab.querySelector(':scope > .fx-actions');if(actions)actions.after(el);else lab.prepend(el);
 el.querySelector('[data-method-result]').addEventListener('click',e=>{e.preventDefault();const target=lab.querySelector('#results,#lab-root,#m2-peak-chart,[data-m2-stage-panel],canvas,svg')||el.nextElementSibling;if(!target)return;target.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});target.setAttribute('tabindex','-1');target.focus({preventScroll:true});});
}
g.S17MethodRole={roles,mount};
if(typeof document==='undefined')return;
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(mount,80),{once:true});else setTimeout(mount,80);
})(typeof window==='undefined'?globalThis:window);


