window.S17NavigationCatalog={"cases":[{"id":"s17-cuttings-lithology","sceneId":"m1","title":"岩屑识别：先看清一粒，再说清一盘","stageId":"mudlogging","stageName":"录井","directory":"cases","summary":"岩性候选应当能回到可见的颗粒和相似样品；统计一盘岩屑时，还必须说清分母。"},{"id":"s17-drilltime-boundaries","sceneId":"m4","title":"钻时分段：钻得变快，先看是谁变了","stageId":"mudlogging","stageName":"录井","directory":"cases","summary":"沿同一深度比较钻速、操作与相对响应，再判断哪里值得进一步核查。"},{"id":"s17-evidence-report","sceneId":"m5","title":"录井报告自动生成","stageId":"mudlogging","stageName":"录井","directory":"cases","summary":"沿井段对照岩屑、气测、荧光和钻时，生成有来处的录井报告与核查问题。"},{"id":"s17-fluorescence-review","sceneId":"m3","title":"荧光显示：看清哪里发光，再量有多大","stageId":"mudlogging","stageName":"录井","directory":"cases","summary":"先把白光与紫外对上同一份样品，再分清曝光影响，用共同分母比较三种显示分割。"},{"id":"s17-mudgas-context","sceneId":"m2","title":"气测异常智能解释：一个气峰的证据之旅","stageId":"mudlogging","stageName":"录井","directory":"cases","summary":"先找回来源时段，再结合工况和组分，才能提出有依据的解释。沿着同一个气峰，看清一条地面记录背后的专业知识。"},{"id":"s17x-c1-cement-quality","sceneId":"c1","title":"固井质量智能评价","stageId":"cementing","stageName":"固井","directory":"expansion-cases","summary":"声波胶结评价要把套管早到波与后到波放在一起；高声幅可能有多种原因。"},{"id":"s17x-c2-cement-displacement","sceneId":"c2","title":"注水泥参数优化","stageId":"cementing","stageName":"固井","directory":"expansion-cases","summary":"注水泥需要把钻井液置换出去；提高排量的收益必须与压力边界一起比较。"},{"id":"s17x-c3-cement-loss-risk","sceneId":"c3","title":"固井漏失风险预测","stageId":"cementing","stageName":"固井","directory":"expansion-cases","summary":"漏失风险分数与报警阈值分开计算；同一批井段可因门槛不同产生不同警报。"},{"id":"s17x-c4-casing-standoff","sceneId":"c4","title":"套管居中度智能评估","stageId":"cementing","stageName":"固井","directory":"expansion-cases","summary":"居中度由窄侧间隙决定；从扶正器位置沿跨距寻找最差间隙。"},{"id":"s17x-co1-completion-choice","sceneId":"co1","title":"完井方式智能优选","stageId":"completion","stageName":"完井","directory":"expansion-cases","summary":"完井方式对应不同的出砂、控水与成本需求；排序前先检查方案能否适用。"},{"id":"s17x-co2-completion-zone-design","sceneId":"co2","title":"射孔参数智能设计","stageId":"completion","stageName":"完井","directory":"expansion-cases","summary":"射孔层段组合要同时考虑产出与含水；组合方案还必须满足压差和预算约束。"},{"id":"s17x-co3-tubing-stress","sceneId":"co3","title":"完井管柱受力智能分析","stageId":"completion","stageName":"完井","directory":"expansion-cases","summary":"管柱受力有轴向、环向等不同方向；应沿深度组合载荷并寻找最不利位置。"},{"id":"s17x-co4-sliding-sleeve-control","sceneId":"co4","title":"智能完井滑套控制策略","stageId":"completion","stageName":"完井","directory":"expansion-cases","summary":"滑套改变各层进流通道；控制效果需要把产油、产水和切换代价一起看。"},{"id":"s17x-d1-rop-optimization","sceneId":"d1","title":"钻速预测与参数优化：从响应面到可行候选","stageId":"drilling","stageName":"钻井","directory":"expansion-cases","summary":"钻得更快需要同时满足泵压、扭矩和参数边界；预测高值要与可行区域一起看。"},{"id":"s17x-d2-drilling-precursor","sceneId":"d2","title":"井下复杂工况预警：先解释正常泵压，再找持续偏离","stageId":"drilling","stageName":"钻井","directory":"expansion-cases","summary":"泵压随正常工况变化；先预测正常响应，再看持续偏离，能帮助区分负荷变化与异常。"},{"id":"s17x-d3-trajectory-control","sceneId":"d3","title":"井眼轨迹控制：学到转向响应后怎样接近目标","stageId":"drilling","stageName":"钻井","directory":"expansion-cases","summary":"轨迹控制要在到达目标与转弯幅度之间权衡；动作响应和轨迹结果应同时展示。"},{"id":"s17x-d4-tool-condition","sceneId":"d4","title":"钻具状态识别：振动变大还是频带变了","stageId":"drilling","stageName":"钻井","directory":"expansion-cases","summary":"振动强度相似的钻具状态，频率组成可能不同；时域与频域需要对照。"},{"id":"s17x-d5-mud-rheology","sceneId":"d5","title":"钻井液性能调控：温度变化下寻找可行塑性黏度","stageId":"drilling","stageName":"钻井","directory":"expansion-cases","summary":"钻井液性能取决于配方和温度；配方搜索应建立在已检验的性能预测上。"},{"id":"s17x-e1-fracture-optimization","sceneId":"e1","title":"压裂参数智能优化：在资源边界里比较候选","stageId":"eor","stageName":"增采","directory":"expansion-cases","summary":"压裂参数要平衡增油、成本与资源边界；高收益点只有满足约束才成为候选。"},{"id":"s17x-e2-fracture-geometry","sceneId":"e2","title":"压裂裂缝形态预测","stageId":"eor","stageName":"增采","directory":"expansion-cases","summary":"裂缝半长与高度是不同方向的尺度；地层约束会改变注入体积的分配。"},{"id":"s17x-e3-chemical-mixture","sceneId":"e3","title":"化学驱配方智能筛选","stageId":"eor","stageName":"增采","directory":"expansion-cases","summary":"化学驱配方的效果依赖环境；先检查性能代理，再在盐度与预算条件下筛配方。"},{"id":"s17x-e4-steam-cycle","sceneId":"e4","title":"蒸汽吞吐注采参数优化","stageId":"eor","stageName":"增采","directory":"expansion-cases","summary":"蒸汽吞吐把注汽、焖井和采油分成阶段；比较效果需要采用相同的热量与时间边界。"},{"id":"s17x-e5-microbial-activity","sceneId":"e5","title":"微生物采油菌群活性预测","stageId":"eor","stageName":"增采","directory":"expansion-cases","summary":"菌群活性随培养环境变化；从相似培养条件理解相对活性。"},{"id":"s17x-g1-remote-lithology","sceneId":"g1","title":"地质剖面遥感解译：从多波段像素读懂地表单元","stageId":"geology","stageName":"地质勘察","directory":"expansion-cases","summary":"露头的颜色同时受岩石、植被和阴影影响；多波段的价值，要在同一位置与单红光判断比较。"},{"id":"s17x-g2-geochemical-anomaly","sceneId":"g2","title":"油气地球化学异常：从单点高值到联合背景偏离","stageId":"geology","stageName":"地质勘察","directory":"expansion-cases","summary":"异常是偏离当地多组分背景的程度；甲烷单点升高还需要回到组分与位置一起解释。"},{"id":"s17x-g3-map-elements","sceneId":"g3","title":"地质图要素提取：把符号与图例变成可检索记录","stageId":"geology","stageName":"地质勘察","directory":"expansion-cases","summary":"地质图包含符号与文字；先比较图块形状，再把图例整理成可检索字段。"},{"id":"s17x-g4-fracture-survey","sceneId":"g4","title":"露头裂缝统计：从暗色迹线到方向与裂缝强度","stageId":"geology","stageName":"地质勘察","directory":"expansion-cases","summary":"裂缝条数和裂缝总长度回答不同问题；统计之前，要先说明观察窗口与检出的线段。"},{"id":"s17x-p1-perforation-design","sceneId":"p1","title":"射孔参数优化：从试验响应到受约束候选","stageId":"perforation","stageName":"射孔","directory":"expansion-cases","summary":"射孔设计建立储层与井筒的流动通道；穿深、孔密和相位需要在预算与干扰下共同比较。"},{"id":"s17x-p2-perforation-shape","sceneId":"p2","title":"射孔孔道形态预测：材料变化如何影响通道？","stageId":"perforation","stageName":"射孔","directory":"expansion-cases","summary":"孔道形态依赖岩石与围压条件；从同一试验体系比较各条件的响应。"},{"id":"s17x-p3-perforation-catalog","sceneId":"p3","title":"射孔弹型智能选型：把目录条件变成证据链","stageId":"perforation","stageName":"射孔","directory":"expansion-cases","summary":"弹型选择先满足通径、温度和岩石条件，再讨论穿深与偏好；缺失条件应保留待查。"},{"id":"s17x-p4-perforation-effect","sceneId":"p4","title":"射孔效果智能评估：把工况变化与效果分开","stageId":"perforation","stageName":"射孔","directory":"expansion-cases","summary":"射孔前后产量还受压差和含水变化影响；先建立稳定工况参照，再看剩余增量。"},{"id":"s17x-pr1-pump-card","sceneId":"pr1","title":"抽油机井工况诊断：从井下泵功图读形状","stageId":"production","stageName":"采油","directory":"expansion-cases","summary":"示功图把一个抽汲周期的载荷与位移配对；形状信息能区分面积相近的泵况。"},{"id":"s17x-pr2-production-forecast","sceneId":"pr2","title":"产量智能预测：用过去推向未来的一小段","stageId":"production","stageName":"采油","directory":"expansion-cases","summary":"产量预测必须沿时间向前；已有趋势、近期波动与未来干预要分开解释。"},{"id":"s17x-pr3-water-allocation","sceneId":"pr3","title":"智能注水调配：有限水量怎样分给三层？","stageId":"production","stageName":"采油","directory":"expansion-cases","summary":"注水分配需要守住总量和各井能力；边际响应不同，平均分水未必最合适。"},{"id":"s17x-pr4-esp-warning","sceneId":"pr4","title":"电潜泵故障预警：先解释负荷，再找额外偏离","stageId":"production","stageName":"采油","directory":"expansion-cases","summary":"电潜泵电流随负荷正常变化；告警更应关注偏离正常关系的持续趋势。"},{"id":"s17x-pr5-wax-risk","sceneId":"pr5","title":"结蜡 / 结垢预测：先把结蜡机理讲清楚","stageId":"production","stageName":"采油","directory":"expansion-cases","summary":"结蜡风险取决于温差、含蜡量与流动条件；多条件分类应与单一温度规则对照。"},{"id":"s17x-r1-distillation-optimization","sceneId":"r1","title":"常减压操作优化：收率、质量与能耗的边界","stageId":"refining","stageName":"加工","directory":"expansion-cases","summary":"常减压操作同时改变馏分收率、能耗与终馏点；在三者的约束内比较候选。"},{"id":"s17x-r2-fcc-product-yields","sceneId":"r2","title":"催化裂化产物预测：一百公斤原料去了哪里","stageId":"refining","stageName":"加工","directory":"expansion-cases","summary":"催化裂化改变分子并分配产品；预测产品收率前后都要核对同一份质量账。"},{"id":"s17x-r3-maintenance-trend","sceneId":"r3","title":"炼化设备预测性维护：先解释负荷，再追踪退化","stageId":"refining","stageName":"加工","directory":"expansion-cases","summary":"设备维护要读持续偏离和频率结构；单次振动升高也可能来自正常负荷变化。"},{"id":"s17x-r4-lab-audit","sceneId":"r4","title":"化验数据智能审核：从原文单位到指标关系","stageId":"refining","stageName":"加工","directory":"expansion-cases","summary":"化验审核先统一单位，再检查跨指标关系；每列都在范围内也可能彼此矛盾。"},{"id":"s17x-r5-quality-softsensor","sceneId":"r5","title":"产品质量在线软测量：化验到来之前","stageId":"refining","stageName":"加工","directory":"expansion-cases","summary":"软测量用过程量估计质量；化验对应较早的物料批次，配对时刻必须先对齐。"},{"id":"s17x-s1-seismic-fault","sceneId":"s1","title":"地震断层自动解释：沿波形不连续性寻找错断","stageId":"seismic","stageName":"物探","directory":"expansion-cases","summary":"断层解释寻找反射的错断关系；不连续也可能来自噪声或缺道，需要逐位置比较。"},{"id":"s17x-s2-seismic-facies","sceneId":"s2","title":"地震相智能分类：从反射纹理认识沉积线索","stageId":"seismic","stageName":"物探","directory":"expansion-cases","summary":"地震相描述一段反射的结构与连续性；振幅相近的窗口也可能属于不同结构。"},{"id":"s17x-s3-first-arrival","sceneId":"s3","title":"初至波自动拾取：把第一段有效能量定位到时间轴","stageId":"seismic","stageName":"物探","directory":"expansion-cases","summary":"初至是最早可辨认的到达；弱起跳和噪声尖峰要求同时检查触发时间与波形。"},{"id":"s17x-s4-reservoir-inversion","sceneId":"s4","title":"储层参数反演：用井震关系估计孔隙度","stageId":"seismic","stageName":"物探","directory":"expansion-cases","summary":"地震属性到孔隙度的映射需要井震标定；相同阻抗可能对应不同的孔隙度。"},{"id":"s17x-s5-seismic-denoise","sceneId":"s5","title":"地震资料噪声压制：降低干扰，也检查反射是否保真","stageId":"seismic","stageName":"物探","directory":"expansion-cases","summary":"去噪既要降低干扰，也要保留反射；被移除的差值图与处理后波形同样需要看。"},{"id":"s17x-t1-pipeline-leak","sceneId":"t1","title":"管道泄漏智能检测：从正常关系到事件核查","stageId":"transport","stageName":"运输","directory":"expansion-cases","summary":"管道泄漏检测先解释负荷变化，再看进出口平衡的持续偏离；漂移与损失需要区分。"},{"id":"s17x-t2-corrosion-growth","sceneId":"t2","title":"管道腐蚀评估：先找对缺陷，再谈增长","stageId":"transport","stageName":"运输","directory":"expansion-cases","summary":"腐蚀增长比较的是两次同一位置的壁损；先对齐再相减，才能解释增长率。"},{"id":"s17x-t3-gathering-pump-optimization","sceneId":"t3","title":"集输工况优化：同样输量怎样少用电","stageId":"transport","stageName":"运输","directory":"expansion-cases","summary":"集输优化先满足输量与扬程，再比较能耗费用；每个图点都应能回查到设备方案。"},{"id":"s17x-t4-meter-drift-calibration","sceneId":"t4","title":"油气计量校正：分清读数变化与仪表偏移","stageId":"transport","stageName":"运输","directory":"expansion-cases","summary":"计量校正用独立参照识别系统偏差；旧系数在新漂移下需要重新检查。"},{"id":"s17x-t5-tank-level-crosscheck","sceneId":"t5","title":"储罐液位监控：图像读数怎样与雷达互相核对","stageId":"transport","stageName":"运输","directory":"expansion-cases","summary":"液位估计要先有高度标尺；视觉和雷达有不同误差，融合需要比较各自观测。"},{"id":"s17x-w1-log-boundaries","sceneId":"w1","title":"测井曲线智能分层：识别持续改变的地层响应","stageId":"welllog","stageName":"测井","directory":"expansion-cases","summary":"分层寻找一段曲线关系的持续改变；单点尖峰和真正界面要用邻域比较。"},{"id":"s17x-w2-porosity-calibration","sceneId":"w2","title":"储层参数智能解释：用岩心标定孔隙度","stageId":"welllog","stageName":"测井","directory":"expansion-cases","summary":"孔隙度解释需要岩石与流体假设；多道标定应与单密度方法在独立点上比较。"},{"id":"s17x-w3-borehole-fractures","sceneId":"w3","title":"成像测井裂缝识别：从井壁展开图分出窄曲线","stageId":"welllog","stageName":"测井","directory":"expansion-cases","summary":"井壁成像是圆柱面的展开图；倾斜裂缝展开成曲线，需要在像素层面识别。"},{"id":"s17x-w4-log-lithology","sceneId":"w4","title":"测井岩性识别：多道曲线与可解释近邻","stageId":"welllog","stageName":"测井","directory":"expansion-cases","summary":"岩性解释利用多道响应互补；流体与井眼也会改变曲线，所以要保留近邻依据。"},{"id":"s17x-w5-curve-repair","sceneId":"w5","title":"测井曲线修复：用可见曲线重建密度缺口","stageId":"welllog","stageName":"测井","directory":"expansion-cases","summary":"缺测曲线的修复值来自其他观测关系；要把原始测量、缺口和估计值明确区分。"},{"id":"s17x-wo1-workover-retrieval","sceneId":"wo1","title":"修井作业方案智能推荐：从井史找到有出处的候选","stageId":"workover","stageName":"修井","directory":"expansion-cases","summary":"修井检索要分清历史怀疑与本次观测；相似工单提供来源，当前条件决定能否推荐。"},{"id":"s17x-wo2-fishing-tools","sceneId":"wo2","title":"落物打捞工具智能选型","stageId":"workover","stageName":"修井","directory":"expansion-cases","summary":"打捞工具必须与落物形状和可用通径匹配；候选依据应能回查到尺寸和载荷。"},{"id":"s17x-wo3-casing-damage","sceneId":"wo3","title":"套管损伤智能识别","stageId":"workover","stageName":"修井","directory":"expansion-cases","summary":"套管展开图里的整体偏心与局部损伤形态不同；先校正背景，再定位局部异常。"},{"id":"s17x-wo4-workover-warning","sceneId":"wo4","title":"修井作业风险预警","stageId":"workover","stageName":"修井","directory":"expansion-cases","summary":"修井钩载随动作变化；用速度解释正常载荷后，再检查持续异常与事件时间。"},{"id":"s17x-wo5-maintenance-interval","sceneId":"wo5","title":"修井周期预测","stageId":"workover","stageName":"修井","directory":"expansion-cases","summary":"修井周期是两次检修之间的间隔；运行条件提供预测依据，误差反映估计的分散。"},{"id":"s17x-c1-cement-woc-strength","sceneId":"c1","title":"候凝强度预测与等待时间评估","stageId":"cementing","stageName":"固井","directory":"expansion-cases","summary":"同一自然龄期不代表同一反应进度：沿温度历史计算等效龄期，预测试样强度与目标交点，并在独立批次上比较忽略温度的基线。"},{"id":"s17x-co3-completion-seal-test","sceneId":"co3","title":"完井隔离段验封与温漂辨识","stageId":"completion","stageName":"完井","directory":"expansion-cases","summary":"先确定受试隔离段与闭阀时间窗，再校准温漂与系统顺应性；从同一压力温度记录估计漏率，保留待复核、缺测和未闭阀的负结果。"},{"id":"s17x-g3-closure-spill","sceneId":"g3","title":"构造图闭合与溢出点识别：一条剖面会漏掉什么","stageId":"geology","stageName":"地质勘察","directory":"expansion-cases","summary":"先读懂储层顶面深度与几何闭合，再在二维图上找到第一次通向外边界的深度。"},{"id":"s17x-p1-perforation-depth-correlation","sceneId":"p1","title":"射孔深度校正：用 GR–CCL 对准目标层","stageId":"perforation","stageName":"射孔","directory":"expansion-cases","summary":"目标层位置已经给定；本例把自然伽马形态、套管接箍和工具记录放到同一深度坐标，判断能否给出可靠的局部校正量。"}]};

